# Проверка простоты числа
def prost(c):
    for q in range(2, int(c ** 0.5) + 1):
        if c % q == 0: return False
    return True

print('--Практическое расширение--')
# Сортировка выбором
def selectionsort(kol, x):
    for i in range(kol):
      ch = min(x[i::])
      ind = x[i::].index(ch)
      x[i], x[ind + i] = x[ind + i], x[i]
    return x

# Бинарный поиск
def binary(sp, l, h, nt):
  sr = 0
  while l <= h:
    mid = (l + h) // 2
    sr += 1
    if sp[mid] == nt:
      return mid, sr
    elif sp[mid] > nt:
      h = mid - 1
    else:
      l = mid + 1
  return -1, sr

# Линейный поиск
def linear(sp, nt, kol):
    sr = 0
    for y in range(kol):
        sr += 1
        if sp[y] == nt:
            return y, sr
    return -1, sr

